  private readonly personPeriodCents = computed(() => {
    const figures = new Map<number, Map<number, number>>(
      this.periods().map((period) => [
        period.id,
        new Map(
          this.people().map((p) => [p.id, fixed(period) ? cents(period.personTotals[p.id] ?? '0.00') : 0]),
        ),
